// Push gate: decides whether a push may go out now. Never sends anything.
// State lives in memory only; a restart forgets the marketing counts.

const DAILY_MARKETING_CAP = 3;
const MARKETING = 'marketing';
const TRANSACTIONAL = 'transactional';

// userId -> Map(localDayKey "YYYY-MM-DD" -> marketing pushes sent that day)
const marketingSent = new Map();
const formatters = new Map();

function formatterFor(timezone) {
  let formatter = formatters.get(timezone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
    });
    formatters.set(timezone, formatter);
  }
  return formatter;
}

// Returns the customer's local day and minute-of-day, or null for an invalid zone.
function localTime(now, timezone) {
  let parts;
  try {
    parts = formatterFor(timezone).formatToParts(now);
  } catch {
    return null;
  }
  const get = (type) => parts.find((p) => p.type === type).value;
  return {
    dayKey: `${get('year')}-${get('month')}-${get('day')}`,
    minuteOfDay: Number(get('hour')) * 60 + Number(get('minute')),
  };
}

// "HH:MM" -> minutes since midnight, or null if malformed.
function parseClock(value) {
  if (typeof value !== 'string') return null;
  const match = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(value);
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
}

// Start minute included, end minute excluded. start > end wraps past midnight.
// start === end is an empty window.
function inWindow(minute, start, end) {
  if (start === end) return false;
  if (start < end) return minute >= start && minute < end;
  return minute >= start || minute < end;
}

function previousDayKey(dayKey) {
  const ms = Date.parse(`${dayKey}T00:00:00Z`) - 2 * 24 * 60 * 60 * 1000;
  return new Date(ms).toISOString().slice(0, 10);
}

function hold(rule) {
  return { send: false, rule };
}

export function decide(candidate, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('decide: now must be a valid Date');
  }
  if (!candidate || typeof candidate !== 'object') return hold('invalid-candidate');
  const { userId, category, timezone, quietStart, quietEnd } = candidate;
  if (typeof userId !== 'string' || userId === '') return hold('invalid-candidate');

  // Transactional pushes (courier arriving, security code) skip the marketing
  // cap and quiet hours. They are not counted toward the cap.
  if (category === TRANSACTIONAL) return { send: true, rule: null };
  if (category !== MARKETING) return hold('invalid-candidate');

  const local = typeof timezone === 'string' ? localTime(now, timezone) : null;
  if (!local) return hold('invalid-timezone');

  const start = parseClock(quietStart);
  const end = parseClock(quietEnd);
  if (start === null || end === null) return hold('invalid-quiet-window');
  if (inWindow(local.minuteOfDay, start, end)) return hold('quiet-hours');

  let days = marketingSent.get(userId);
  if (!days) {
    days = new Map();
    marketingSent.set(userId, days);
  }
  if ((days.get(local.dayKey) ?? 0) >= DAILY_MARKETING_CAP) return hold('daily-cap');

  days.set(local.dayKey, (days.get(local.dayKey) ?? 0) + 1);
  // Keep today, yesterday and the day before (small clock skew between callers).
  const oldest = previousDayKey(local.dayKey);
  for (const key of days.keys()) {
    if (key < oldest) days.delete(key);
  }
  return { send: true, rule: null };
}

input.command:
node -v && node --input-type=module <<'EOF'
import { decide } from './bot.mjs';
const ok = (name, cond) => { console.log(cond ? 'PASS' : 'FAIL', name); if (!cond) process.exitCode = 1; };
const base = { userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30' };
const at = (iso) => new Date(iso);

// Istanbul is UTC+3 (no DST). 2026-10-23 12:00 local = 09:00Z
const noon = at('2026-10-23T09:00:00Z');
ok('marketing allowed at noon', JSON.stringify(decide({ ...base }, noon)) === '{"send":true,"rule":null}');
decide({ ...base }, noon); decide({ ...base }, noon); // 3 total
ok('4th same local day -> daily-cap', JSON.stringify(decide({ ...base }, noon)) === '{"send":false,"rule":"daily-cap"}');
ok('transactional bypasses cap', decide({ ...base, category: 'transactional' }, noon).send === true);
ok('cap user isolation', decide({ ...base, userId: 'u2' }, noon).send === true);

// Local day boundary: 2026-10-23 23:30 local = 20:30Z; 00:30 local next day = 21:30Z (quiet -> use other user)
const lateEve = at('2026-10-23T20:30:00Z'); // 23:30 local -> quiet hours (wraps)
ok('quiet hours wrap: 23:30 blocked', JSON.stringify(decide({ ...base, userId: 'q' }, lateEve)) === '{"send":false,"rule":"quiet-hours"}');
ok('quiet end exclusive: 07:30 allowed', decide({ ...base, userId: 'q' }, at('2026-10-23T04:30:00Z')).send === true); // 07:30 local
ok('quiet start inclusive: 22:00 blocked', decide({ ...base, userId: 'q2' }, at('2026-10-23T19:00:00Z')).rule === 'quiet-hours'); // 22:00 local
ok('07:29 blocked', decide({ ...base, userId: 'q3' }, at('2026-10-23T04:29:00Z')).rule === 'quiet-hours');
ok('transactional during quiet hours allowed', decide({ ...base, category: 'transactional' }, lateEve).send === true);

// Next local day resets the cap for the same user. Local 2026-10-24 12:00 = 09:00Z
ok('next local day resets cap', decide({ ...base }, at('2026-10-24T09:00:00Z')).send === true);

// Day is customer-local, not UTC: New York 2026-10-23 20:00 local = 2026-10-24T00:00Z
const ny = { ...base, userId: 'ny', timezone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00' };
decide(ny, at('2026-10-24T00:00:00Z')); decide(ny, at('2026-10-24T00:30:00Z')); decide(ny, at('2026-10-24T01:00:00Z'));
ok('local day counted in NY, 4th blocked even though UTC day is next', decide(ny, at('2026-10-24T01:30:00Z')).rule === 'daily-cap');

// Invalid inputs hold
ok('bad zone held', decide({ ...base, timezone: 'Mars/Olympus' }, noon).rule === 'invalid-timezone');
ok('bad window held', decide({ ...base, quietStart: '25:00' }, noon).rule === 'invalid-quiet-window');
ok('missing window held', decide({ ...base, quietEnd: undefined }, noon).rule === 'invalid-quiet-window');
ok('bad category held', decide({ ...base, category: 'promo' }, noon).rule === 'invalid-candidate');
let threw = false; try { decide({ ...base }, new Date('x')); } catch { threw = true; }
ok('invalid now throws', threw);
EOF
